// Workflow script: one batch of the compile-path ladder climb.
//
// Generalised 2026-09-19 from the script that ran climb batch 1, so that the
// next batch is a MANIFEST CHANGE AND NOTHING ELSE: the coordinator replaces the
// block marked "MANIFEST" below and launches. Batch 1's manifest is kept below
// the "END MANIFEST" line as BATCH_1_EXAMPLE, the worked example, which the
// script does not use.
//
// The changes this revision carries are the six process decisions Pavol took on
// 2026-09-19 (POSITIONS.md, "after climb batch 1 landed"), as
// explorations/coordinator/process-decisions-review-1.md amended them, plus the
// eight free changes of repair-batch-review.md section 10. What each stage does
// now and which review item each change answers is written up in
// explorations/coordinator/climb-batch-workflow.md.
//
// Launch, after the worktrees exist (remote-container.md, "Setting up a batch's
// worktrees"):
//   Workflow({scriptPath: 'explorations/coordinator/climb-batch-workflow.js',
//             args: {base: '<the commit main is at>'}})
//
// Every worker, skeptic, gather, review and gate agent is pinned to Opus; the
// judge inherits the session's model. No backticks anywhere in this file.

export const meta = {
  name: 'fortress-climb-batch',
  description: 'One batch of Fortress compile-ladder rungs in isolated worktrees, each judged by its own skeptic, gathered, reviewed and gated once (suite counts, four-thread atomic runs, ladder regression, the checker count over the interpreter library) before it lands',
  phases: [
    { title: 'Rung', detail: 'test-first repair in an isolated worktree, committed and pushed to wip/ as it goes; never runs the full gate' },
    { title: 'Skeptic', detail: 'independent judgement with its own walk-vs-compiled differential; one repair round allowed' },
    { title: 'Judge', detail: 'the session model, only on a refusal, a stop or a red gate: reads the reports and the diff, decides, writes the decision' },
    { title: 'Gather', detail: 'net change of each approved branch applied to main, record folded, one local commit per rung' },
    { title: 'Review', detail: 'the merged diff against the batch rules and the folded record as a whole; runs beside the gate' },
    { title: 'Gate', detail: 'compileAll, library rebuild, testFast, testSystem, the summary diff, the four-thread atomic runs, the ladder regression and the checker count over the interpreter library' },
    { title: 'Commit', detail: 'hashes into the ledger notes, push main, fast-forward the container branch, remove the worktrees' },
  ],
}

const OPUS = 'opus'   // every worker, skeptic, gather, review and gate agent; the judge inherits the session's model
const BASE = args && args.base
if (!BASE) throw new Error('args.base is required: the commit every wip/ branch was cut from')
const CONTAINER_BRANCH = 'claude/worker-brief-fable-vnnuv8'   // this container's infrastructure branch; kept at main
const MAIN = '/home/user/fortress'

// ===========================================================================
// MANIFEST - the coordinator replaces everything between this line and the
// "END MANIFEST" line, and changes nothing else in this file.
//
// Concurrency, which the manifest does NOT set: the harness runs at most two
// agents at once here (min(16, nproc - 2) with nproc 4; measured 2026-09-18,
// FACTS.md, "The container"), and a freed slot goes to the next queued agent,
// FIFO, not to the finished rung's skeptic (measured over batch 1's journal,
// FACTS.md, "The compile-path ladder baseline", the bullet beginning "The
// harness's freed slots go to the next worker"). Batch size k was 4 in batch 1
// and 3 in batch 2, and is 6 here, the largest yet (CLIMB-BATCH-3.md, "How it is
// run", rule 4); the saving is gate amortisation, not concurrency
// (batched-climb-plan.md section 2), and the cap of two agents at a time is what
// sets the wall.
// One chain per rung was priced against batch 1's own agent walls and rejected -
// it saves 0.3 minutes (process-decisions-review-1.md, decision 2(a)) - so it is
// deliberately not implemented here. What IS taken from that finding is the
// expectedMinutes field below: the scatter starts the longest-expected worker
// first, worth 0-12 minutes when the guess is right.
//
// Per rung: id, slug, worktree path, branch, expectedMinutes (the worker's own
// wall, used only for the start order), tail (its brief), blurb (one line for
// the shared prefix's manifest table), writesState (true if the rung touches a
// mutable variable, a field, atomic, or library code that writes - it makes the
// skeptic run every differential at one thread and at four), and expectedMoves
// (ladder files the rung changes on purpose, each with the phase or output it is
// expected to reach; anything else that moves down is red).
// Three optional per-rung fields serve the checker-count stage (gate step 8),
// which runs the compiler's static checker over the interpreter's library:
// testIsStage (true when that stage's table before and after the edit IS this
// rung's failing-then-passing test, so the rung's step 1 asks for the table and
// not for a .fss program - library-route-judgement.md section 2 step 1, the one
// place the test-first rule is met by a stage, because no program can yet be
// compiled against that prelude), expectedCheckerCount (the error total the rung
// expects the stage to print after its edit; without it a total ABOVE the last
// landed one is red) and expectedCheckerCrash (the crash line the rung expects
// instead of the landed one, or the literal none when it removes the crash).
//
// Batch 3's values are CLIMB-BATCH-3.md, "The machine-read fields". Each tail is
// that rung's section under "The six rungs" word for word, with the record's
// code-span backticks dropped (this file carries none) and its non-ASCII
// characters written as \u escapes. The RUNGS array is in manifest order (P, L,
// C, R, S, M), which is the order the gather numbers new ledger rows in; the
// scatter sorts it by expectedMinutes, longest first: P, L, S, M, R, C.
// The checker count: P declares 33 (its hierarchy half alone on its own branch)
// and L declares 102 (its own branch, the one declaration above the last landed
// 93, and so the one that does gate work: if L lands without P the merged table
// reads 102 and passes as a declared rise). The merged tree's expected total with
// every rung landed is 23 (22 with the closure's checker accommodation, which
// this batch leaves out; perf-probes/nat/triage.md section 5, r17 and r18). The
// gate reads only the per-rung fields, so the 23 is stated here and not as a
// field: with P and L both landed it is a fall, green without a declaration. No
// rung sets expectedCheckerCrash: the Not yet implemented crash at
// STypesUtil.scala:557 does not move in this batch, and the gate is red if it
// does. No rung declares a ladder move (the record gives the reason per rung).
// ===========================================================================

const BATCH = 3
const BATCH_RECORD = 'explorations/coordinator/CLIMB-BATCH-3.md'
const BATCH_INTRO = 'This batch is the first batch of the library route decided 2026-09-21: two rungs take the checker\'s error count over the interpreter\'s library from 93 to 23 (the checker\'s exclusion clause the specification contradicts, and the library\'s five plain api defects), and four small rungs land what Pavol decided on 09-21 and 09-22 - four comments, round half to even on a float, the bare Fortress type name as the compiled default asString, and the analyzer memo.'
const BATCH_OVERLAPS = 'Two pairs share a file and are line-disjoint within it, so the gather applies the batch in ascending order of lowest edited line and re-anchors every shifted citation by symbol: P edits TypeAnalyzer.scala at :443-457, TypeHierarchyChecker.scala at :178,:187 and, for its overloading half, OverloadingChecker.scala at checkOverloading (:159) unless it takes the broad form in pExcInner, while M edits TypeAnalyzer.scala at :722 and :747 plus TraitTable.scala; L edits Library/RangeInternals.fsi, Library/List.fsi and Library/FortressLibrary.fsi at :373, :789 and :2311-2328 while C edits Library/FortressLibrary.fss and .fsi at the closure, the Array3 clause and the scalar block. R edits interpreter glue only and S the compiler prelude plus one nativeHelpers file; neither meets another rung.'
const LEDGER_FROM = 354   // the first free ledger row number when the batch was planned (the ledger's highest row is 353; batch 2 opened 343-353)

const P_TAIL = [
"",
"## Your rung: P - the checker's exclusion relaxation",
"",
"SLUG is rung-exclusion-relax. WORKTREE is /home/user/fortress-exclusion, branch wip/rung-exclusion-relax.",
"",
"Your brief is this rung's section of the batch record (explorations/coordinator/CLIMB-BATCH-3.md, under \"The six rungs\"), carried below word for word; where it says what the rung does, decides or records, that is you.",
"",
"**The measurement.** perf-probes/prelude/exclusion-trace.md bucket 2: of the 93 errors the checker reports over the interpreter's library, **61 at 26 sites** are caused by checkP and by nothing else \u2014 checkEC fires once in the whole set, checkO never, and checkCC, which fires alongside checkP at 29 of them, establishes nothing on its own (measured: relaxing checkP and checkCC together gives a byte-identical error list to relaxing checkP alone, 02-dropP.out against 03-dropP-dropCC.out). Relaxing checkP in the positive direction takes the count to **33**, and confining that relaxation to the two TypeHierarchyChecker call sites gives **33 as well, with the same three residual sites** (12-hierarchyOnly.out). Per-error attribution, with the generic each pair inherits at two instantiations, is exclusion-trace/sites.tsv.",
"",
"**Why the clause is the checker's defect and not the library's.** Specification/basic/trait-parameters.tex:339-345 says trait declarations are allowed to extend other instantiations of themselves. The specification's list of what makes two types exclusive has four entries \u2014 an excludes clause (types-vals-vars.tex:212-214), object-ness (:222-224), propagation to subtypes (:163-164), and the arrow, tuple, () and BottomType cases (:215-216) \u2014 and two instantiations of one generic are not among them. The library's shape is not exotic: because its algebra traits are parameterised by their own subject type (Equality[\\T\\], StandardTotalOrder[\\T\\], Integral[\\I\\]), any nested tower inherits one of them twice, so checkP declares ZZ32 and ZZ64 to share no value. The interpreter's own exclusion relation (FType.java:196-297) has no instantiation clause at all, and the designers' survey says the same: \"two instantiations of Array are neither ordered nor excluding\".",
"",
"**The two caveats the trace carries, which the rung must carry too.** First, **the specification's own example cannot be put through this front end** \u2014 as printed it gives \"T is undefined\" twice, because a where-clause variable is not in scope in an extends clause, and rewritten with two static parameters it is refused earlier as \"Cyclic type hierarchy\" with or without the relaxation (09-spec-self-instantiation.out, 09a-\u2026, 17-SelfInst2-*.out). So trait-parameters.tex:339-345 is cited as text, and the demonstration is MinP.fss, the library's own shape in three traits, where the specification offers no rule that makes the two types exclusive at all. Second, **the trace does not settle soundness**: dropping checkP in the positive direction only makes excludes and notExcludes no longer complementary \u2014 definitelyExcludes(List[\\ZZ32\\], List[\\Boolean\\]) becomes false while notExcludes still emits the equality constraint $i=$j that static-argument inference runs on \u2014 and nothing in the trace measures what the inference path does with that. The gate for this rung is the full suite, which the trace never ran, and nor did the triage (\u00a7 6): no suite has yet run with the relaxation in any placement, and covering the overloading check widens what that run has to show. The clause must not be deleted: under negate = true it is what notExcludes (TypeAnalyzer.scala:367-370) uses to emit those constraints, in the team's own words at :361-365.",
"",
"**The decision the rung carries: where the relaxation goes, now settled by measurement to include the overloading check.** definitelyExcludes is called from the two hierarchy checks (TypeHierarchyChecker.scala:178, :187), from CoercionOracle.scala:78, :82 and from Formula.scala:189, :191, :295, :304, :307, and excludes from OverloadingChecker.scala:478, :491, which is the Incompatibility Rule's certificate. This record first recommended the two hierarchy call sites alone, because both placements gave 33 on this library and the narrow one left overload checking and coercion with the strong rule. The triage measured that reason away (perf-probes/nat/triage.md \u00a7 2, \u00a7 5): the two agree on today's library, where early errors keep the overloading check off RangeInternals and FortressLibrary, but once L's bounds let it run on RangeInternals, the strong clause, still feeding OverloadingOracle.excludes \u2014 \"the meet of the two domains is Bottom\" (overloading/OverloadingOracle.scala:190-194), Bottom when normConjunct finds two excluding conjuncts (TypeAnalyzer.scala:632-640) \u2014 makes a subtype in the nested tower exclude its own supertype and refuses pairs where the Subtype Rule plainly holds, combine2D(ExtentScalarRange, ExtentScalarRange) against combine2D(ScalarRange, ScalarRange) among them. Measured on today's tree with L's library: the hierarchy call sites alone, **41** (r11); the relaxation raised for the overloading check too, **23** (r17: 19 RangeInternals errors gone, CAP 5 and combine2D/combine3D 14, and one exposed, an IN pair that only the strong clause certified); with everything applied (the triage's ZALL3, memo off), 487 against 203. **So the rung covers the overloading checker's exclusion test as well as the two hierarchy questions** \u2014 the direction the interpreter already takes, its exclusion relation having no instantiation clause at all. The measured form raises the relaxation for the whole overloading check (OverloadingChecker.checkOverloading, :159; the triage's -Dprobe.triage.dropPOver, triage/overloading-checker.patch) and leaves CoercionOracle and Formula with the strong rule; on this library it gives the same error list as the broad placement inside pExcInner (203 and 203, triage \u00a7 2), and what either does to coercion and inference elsewhere is unmeasured. The probe's switch twins every analyzer memo while the relaxation is raised (triage/p-only.patch), so that no answer computed under it is read outside it; a scoped placement has to solve the same, and the broad one does not. The rung records its choice between the two and what it leaves unmeasured.",
"",
"**The test, first.** ProjectFortress/compiler_tests/ExclusionRelaxRungP.fss + .test in the form of compiler_tests/AtomicTopLevelVar.test (tests=ExclusionRelaxRungP, link, run, run_out_contains=PASS, run_out_does_not_contain=FAIL): the shape of perf-probes/prelude/exclusion-trace/MinP.fss \u2014 trait G[\\X\\] end, trait A extends G[\\ZZ32\\] end, trait B extends { A, G[\\Boolean\\] } end, no excludes and no comprises in the file \u2014 with a run() that prints PASS. Capture the four errors before the edit (two family A, two family B, every one attributed clause=P; 17-MinP-stock.out is the trace's own capture of them, 17-MinP-dropP.out the relaxed run at 0 errors and rc=0). The test must stay a *positive* test: it is the specification's rule, so a program of this shape compiling is the assertion. The overloading half has no program of its own in this record: on this rung's own branch its effect is unmeasured, and on the count it shows only once L's bounds let RangeInternals' overloading check run, so its evidence is the triage's captures (r11 against r17) and its verification is the merged tree, the second declared exception to rule 2 (\"How it is run\"); a program reducing one of the refused pairs, as MinP.fss reduces the hierarchy half, would be the better test and was not attempted.",
"",
"**What it clears, and the stop.** On the count stage: 93 \u2192 33 on this rung's own branch for the hierarchy half (r13, and the trace's 12-hierarchyOnly.out), the overloading half's effect there unmeasured and named in the report; on the merged tree with L, 23 where the hierarchy half alone gives 41 (r17, r11). On the ladder: nothing declared. The rung stops and reports rather than half-landing if the suite goes red in the inference path and the fix for that is a second design decision \u2014 that is the one thing the trace says it cannot predict. It must not touch the library, must not remove checkP, and must not change notExcludes.",
"",
].join('\n')

const L_TAIL = [
"",
"## Your rung: L - the library's five plain defects",
"",
"SLUG is rung-library-defects. WORKTREE is /home/user/fortress-defects, branch wip/rung-library-defects.",
"",
"Your brief is this rung's section of the batch record (explorations/coordinator/CLIMB-BATCH-3.md, under \"The six rungs\"), carried below word for word; where it says what the rung does, decides or records, that is you.",
"",
"**The measurement.** Trace bucket 1 and families C, D and F of coordinator/two-libraries.md \u00a7 3, re-counted for that brief rather than taken from the record: 26 errors of family C at 15 sites, 2 of family D at 2 sites, 1 of family F (plus 1 secondary), and one of the two family E errors free. In the trace's own composition of the 32 that remain after P (\u00a7 7, 19-lib-L1b-dropP.out), these are 26 + 2 + 2, and the second family F error is the one P's relaxation unmasks.",
"",
"**The five, each with its site and its rule.**",
"",

// Back into manifest order: the ledger numbers and the record are ordered by the
// manifest, never by the order the scatter happened to run in.
const byId = {}
for (const r of results.filter(Boolean)) byId[r.rung] = r
const rungs = RUNGS.map(r => byId[r.id]).filter(Boolean)
const approved = rungs.filter(r => r.state === 'approved' || r.state === 'approved-after-repair')
const notLanded = rungs.filter(r => r.state !== 'approved' && r.state !== 'approved-after-repair')
const expectedMoves = [].concat.apply([], RUNGS.filter(m => approved.some(a => a.rung === m.id)).map(m => (m.expectedMoves || []).map(x => m.id + ': ' + x)))
// The checker-count stage's declarations, gathered the same way: only an approved
// rung's declaration counts, because a rung that did not land changed nothing.
const expectedChecker = {
  counts: RUNGS.filter(m => approved.some(a => a.rung === m.id) && m.expectedCheckerCount !== undefined)
               .map(m => m.id + ': ' + m.expectedCheckerCount),
  crashes: RUNGS.filter(m => approved.some(a => a.rung === m.id) && m.expectedCheckerCrash !== undefined)
                .map(m => m.id + ': ' + m.expectedCheckerCrash),
}
const report = { batch: BATCH, base: BASE, rungs }

if (approved.length === 0) {
  log('No rung approved; nothing to gather. ' + rungs.map(r => r.rung + ': ' + r.state).join(', '))
  return Object.assign(report, { landed: false, reason: 'no rung approved' })
}
log('Approved: ' + approved.map(r => r.rung + ' (' + r.state + ')').join(', ')
    + (notLanded.length ? '. Not landed, findings folded anyway: ' + notLanded.map(r => r.rung + ' (' + r.state + ')').join(', ') : '')
    + '. Gathering onto main.')

// Gather: one composed local commit per approved rung, plus the not-landed findings.
const gather = await agent(PREFIX + gatherRole(approved, notLanded), { label: 'gather', phase: 'Gather', schema: GATHER_SCHEMA, model: OPUS })
report.gather = gather
if (!gather || gather.unresolved) {
  log('Gather stopped: ' + ((gather && gather.summary) || 'agent died'))
  return Object.assign(report, { landed: false, reason: 'gather unresolved' })
}

// Review BESIDE the gate. The review reads the merged diff and never builds; the
// gate builds and never reads the record. Batch 1 ran them one after the other
// and the review's 14.7 minutes were serial for nothing
// (process-decisions-review-1.md, decision 2(a), "What buys time in the same
// place"). The named risk is two agents committing in this tree at once, and it
// is closed by the gate committing nothing: the commit stage adds its summary.
let [review, gate] = await parallel([
  () => agent(PREFIX + reviewRole(gather), { label: 'review', phase: 'Review', schema: REVIEW_SCHEMA, model: OPUS }),
  () => agent(PREFIX + gateRole(expectedMoves, expectedChecker), { label: 'gate', phase: 'Gate', schema: GATE_SCHEMA, model: OPUS }),
])
report.review = review
report.gate = gate

// A blocking review means a judge and a repair on the merged tree, and the gate
// that ran beside it is discarded: the source has changed under it.
let gateIsStale = !!(review && review.pathsOutsideExplorations && review.pathsOutsideExplorations.length)
if (gateIsStale) {
  log('The review\'s corrections touched ' + review.pathsOutsideExplorations.length + ' path(s) outside explorations/ ('
      + review.pathsOutsideExplorations.join(', ') + '); the gate that ran beside it is stale and runs again')
}

if (review && !review.approved && review.blocking && review.blocking.length) {
  log('Review found blocking: ' + review.blocking.length + ' item(s); the judge rules')
  const decision = await agent(PREFIX + judgeRole('review', null, null, null, review), { label: 'judge:review', phase: 'Judge', schema: JUDGE_SCHEMA })
  report.reviewJudge = decision
  if (!decision || decision.decision !== 'repair') {
    return Object.assign(report, { landed: false, reason: 'review blocking, judge did not order a repair' })
  }
  await agent(PREFIX + mergedRepairRole(decision, 'review'), { label: 'repair:review', phase: 'Review', schema: RUNG_SCHEMA, model: OPUS })
  review = await agent(PREFIX + reviewRole(gather), { label: 'review2', phase: 'Review', schema: REVIEW_SCHEMA, model: OPUS })
  report.review2 = review
  if (!review || !review.approved) {
    return Object.assign(report, { landed: false, reason: 'review still blocking after one repair' })
  }
  gateIsStale = true
}

if (gateIsStale || !gate) {
  gate = await agent(PREFIX + gateRole(expectedMoves, expectedChecker), { label: 'gate:after-review', phase: 'Gate', schema: GATE_SCHEMA, model: OPUS })
  report.gateAfterReview = gate
}

if (!gate || gate.stopped) {
  return Object.assign(report, { landed: false, reason: 'gate could not run' })
}
if (!gate.green) {
  log('Gate red: ' + gate.failing.length + ' failing; the judge diagnoses on the merged tree')
  const decision = await agent(PREFIX + judgeRole('gate', null, null, null, gate), { label: 'judge:gate', phase: 'Judge', schema: JUDGE_SCHEMA })
  report.gateJudge = decision
  if (!decision || decision.decision !== 'repair') {
    return Object.assign(report, { landed: false, reason: 'gate red, judge did not order a repair' })
  }
  await agent(PREFIX + mergedRepairRole(decision, 'gate'), { label: 'repair:gate', phase: 'Gate', schema: RUNG_SCHEMA, model: OPUS })
  gate = await agent(PREFIX + gateRole(expectedMoves, expectedChecker), { label: 'gate2', phase: 'Gate', schema: GATE_SCHEMA, model: OPUS })
  report.gate2 = gate
  if (!gate || !gate.green) {
    log('Gate red after one repair: the batch stops here, nothing pushed; the failing tests and the diagnosis are the record')
    return Object.assign(report, { landed: false, reason: 'gate red twice' })
  }
}

// Commit: hashes into the notes, the gate summary added, push, fast-forward the
// container branch, clean up.
const commit = await agent(PREFIX + commitRole(gather, gate), { label: 'commit', phase: 'Commit', schema: COMMIT_SCHEMA, model: OPUS })
report.commit = commit
return Object.assign(report, { landed: !!(commit && commit.pushed && commit.pushed.length) })

